 const caseMaterial=new THREE.MeshPhysicalMaterial({name:'Brushed silver alloy',color:0xa8a9a3,metalness:1,roughness:.27,clearcoat:.25,clearcoatRoughness:.3});const dark=new THREE.MeshStandardMaterial({name:'Black inset',color:0x030405,metalness:.4,roughness:.25});const strap=new THREE.MeshStandardMaterial({name:'Woven nylon loop',color:0x111311,roughness:.94,bumpMap:weaveTexture(),bumpScale:.026,side:THREE.DoubleSide});const thread=new THREE.MeshStandardMaterial({name:'Herringbone threads',color:0x252823,roughness:.95});const red=new THREE.MeshStandardMaterial({name:'Dark red crown ring',color:0x8e1720,metalness:.45,roughness:.35});
